import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry min_reduce_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 outer_size,
    .param .u32 reduce_size,
    .param .u32 inner_size
)
{
    .reg .u32 %r<20>;
    .reg .u64 %rd<20>;
    .reg .f32 %f<10>;
    .reg .pred %p<5>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [outer_size];
    ld.param.u32 %r2, [reduce_size];
    ld.param.u32 %r3, [inner_size];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    // total = outer_size * inner_size
    mul.lo.u32 %r4, %r1, %r3;

    // tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r5, %ctaid.x;
    mov.u32 %r6, %ntid.x;
    mov.u32 %r7, %tid.x;
    mad.lo.u32 %r8, %r5, %r6, %r7;

    setp.ge.u32 %p1, %r8, %r4;
    @%p1 bra DONE;

    // o = tid / inner_size ; i = tid % inner_size
    div.u32 %r9, %r8, %r3;
    mul.lo.u32 %r10, %r9, %r3;
    sub.u32 %r11, %r8, %r10;

    // base_offset_elems = o * reduce_size * inner_size + i  (64-bit)
    cvt.u64.u32 %rd3, %r9;      // o
    cvt.u64.u32 %rd4, %r2;      // reduce_size
    cvt.u64.u32 %rd5, %r3;      // inner_size
    cvt.u64.u32 %rd6, %r11;     // i

    mul.lo.u64 %rd7, %rd4, %rd5;   // reduce_size*inner_size
    mul.lo.u64 %rd8, %rd3, %rd7;   // o*reduce_size*inner_size
    add.u64 %rd9, %rd8, %rd6;      // base_offset_elems

    // load x[base]
    mul.lo.u64 %rd10, %rd9, 4;
    add.u64 %rd11, %rd1, %rd10;
    ld.global.f32 %f1, [%rd11];

    // loop r = 1 .. reduce_size-1
    mov.u32 %r12, 1;
LOOP:
    setp.ge.u32 %p2, %r12, %r2;
    @%p2 bra ENDLOOP;

    cvt.u64.u32 %rd12, %r12;
    mul.lo.u64 %rd13, %rd12, %rd5;
    add.u64 %rd14, %rd9, %rd13;
    mul.lo.u64 %rd15, %rd14, 4;
    add.u64 %rd16, %rd1, %rd15;

    ld.global.f32 %f2, [%rd16];
    min.f32 %f1, %f1, %f2;

    add.u32 %r12, %r12, 1;
    bra LOOP;

ENDLOOP:
    cvt.u64.u32 %rd17, %r8;
    mul.lo.u64 %rd18, %rd17, 4;
    add.u64 %rd19, %rd2, %rd18;
    st.global.f32 [%rd19], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("min_reduce_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs min reduction over a specific dimension
    using a custom PTX kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Input must be float32"

        x = x.contiguous()
        shape = list(x.shape)
        ndim = x.dim()
        dim = self.dim if self.dim >= 0 else self.dim + ndim

        outer_size = 1
        for s in shape[:dim]:
            outer_size *= s

        reduce_size = shape[dim]

        inner_size = 1
        for s in shape[dim + 1:]:
            inner_size *= s

        out_shape = shape[:dim] + shape[dim + 1:]
        output = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        total = outer_size * inner_size
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        if grid_x < 1:
            grid_x = 1

        module = _get_ptx_module()
        module.launch(
            "min_reduce_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                output,
                i32(outer_size),
                i32(reduce_size),
                i32(inner_size),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

